type Server struct {
	name string
	cmd  *exec.Cmd
	done chan struct{}
}

type version struct {
	major int
	minor int
	patch int
}

func redisServerVersion() (*version, error) {

version, err := redisServerVersion()
if err != nil {
	return nil, err
}

if version.major >= 7 {
	args = append(args, "--enable-debug-command", "local")
}

s := &Server{
	name: name,
	cmd:  exec.Command(*serverPath, args...),
	done: make(chan struct{}),
}

r, err := s.cmd.StdoutPipe()
if err != nil {
	return nil, err
}

err = s.cmd.Start()
if err != nil {
	return nil, err
}

ready := make(chan error, 1)
go s.watch(r, ready)

